export function nextGeneration(cells: Cell[]): Cell[] {
  const living = new Set(cells.map(key));

  const candidates = new Map<string, Cell>();
  for (const cell of cells) {
    for (const neighbor of neighbors(cell)) {
      candidates.set(key(neighbor), neighbor);
    }
    candidates.set(key(cell), cell);
  }

  const survivors: Cell[] = [];
  for (const [candidateKey, cell] of candidates) {
    const liveNeighbors = neighbors(cell).filter((n) =>
      living.has(key(n)),
    ).length;
    const isAlive = living.has(candidateKey);

    if (liveNeighbors === 3 || (isAlive && liveNeighbors === 2)) {
      survivors.push(cell);
    }
  }

  return survivors;
}

