export function nextGeneration(cells: Cell[]): Cell[] {
  const living = new Set(cells.map(cellKey));

  // Every live cell adds one to each of its 8 neighbors, so the tally holds
  // both the candidate cells and their live-neighbor counts in one pass.
  const liveNeighborCounts = new Map<string, { cell: Cell; count: number }>();
  for (const cell of cells) {
    for (const neighbor of neighbors(cell)) {
      const entry = liveNeighborCounts.get(cellKey(neighbor)) ?? {
        cell: neighbor,
        count: 0,
      };
      entry.count += 1;
      liveNeighborCounts.set(cellKey(neighbor), entry);
    }
  }

  const nextCells: Cell[] = [];
  for (const [key, { cell, count }] of liveNeighborCounts) {
    if (count === 3 || (count === 2 && living.has(key))) {
      nextCells.push(cell);
    }
  }

  return nextCells;
}
